-- P3-01 (ADR-0028): habit domain model — categories, habits, schedule versions, recorded
-- occurrences, notes and pauses. Owned by the `habits` module.
-- Additive only: one trusted extension, four enum types, six tables with their indexes, foreign
-- keys and CHECK/EXCLUDE constraints. Nothing existing is altered. Rollback before real data
-- exists: drop the six tables, the four types and (if unused elsewhere) the btree_gist extension.
--
-- Generated by `prisma migrate diff`, then the constraints Prisma cannot express were added by hand
-- at the end (kept in step with HABIT_LIMITS in @habit/shared-validation by
-- src/modules/habits/habits.schema.test.ts). Calendar days are `date` columns holding the user's
-- local date; the window 2000-01-01..2099-12-31 is HABIT_DATE_MIN..HABIT_DATE_MAX.

-- btree_gist lets one GiST index combine "same habit" (uuid =) with "date ranges overlap" (&&).
-- It is a trusted extension (PostgreSQL 13+), so the database owner needs no superuser rights.
CREATE EXTENSION IF NOT EXISTS "btree_gist";

